'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>(window.RON_REGION==='au'?'AU$':'£')+Number(n).toLocaleString('en-GB',{maximumFractionDigits:0}),when=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
let ledger;try{ledger=JSON.parse(localStorage.getItem((window.RON_REGION==='au'?'ron-au-office-v1':'ron-office-v3')))}catch{}if(!ledger?.positions)ledger=structuredClone(originalSeed);
const defaults={assetPurposes:{global:'Long-term growth',uk:'Regular income',bonds:'Regular income',gilts:'Planned investment funding',isa:'Long-term growth',gia:'Long-term growth'},cash:{cash:{spending:20000,tax:30000,committed:0,available:50000},ficcash:{spending:25000,tax:25000,committed:0,available:100000}},docs:[],requests:[],approved:[],audit:[]};let state;try{state=JSON.parse(localStorage.getItem((window.RON_REGION==='au'?'ron-au-simple-v1':'ron-simple-v1')))}catch{}if(!state?.cash)state=structuredClone(defaults);state.assetPurposes=state.assetPurposes||{global:'Long-term growth',uk:'Regular income',bonds:'Regular income',gilts:'Planned investment funding',isa:'Long-term growth',gia:'Long-term growth'};const persist=()=>localStorage.setItem((window.RON_REGION==='au'?'ron-au-simple-v1':'ron-simple-v1'),JSON.stringify(state));
const owners={household:'Personal',fic:'2LR Investments Ltd',propertyco:'2LR Property Ltd'};let moneyFilter='all';
function company(id){return ledger.companies.find(c=>c.id===id)}function debt(id){return ledger.loans.filter(l=>l.borrower===id).reduce((a,l)=>a+l.balance,0)}function value(p,seen=new Set()){if(!p.company)return p.qty*p.price;const c=company(p.company);if(!c?.controlled)return p.qty*(c?.marketPrice||p.price);if(seen.has(c.id))throw Error('Circular ownership');const next=new Set(seen);next.add(c.id);const nav=ledger.positions.filter(x=>x.owner===c.id).reduce((a,x)=>a+value(x,next),0)-debt(c.id);return nav*p.qty/c.shares}function wealth(){return ledger.positions.filter(p=>p.owner==='household').reduce((a,p)=>a+value(p),0)+ledger.loans.reduce((a,l)=>a+l.balance,0)}
const cashPositions=()=>ledger.positions.filter(p=>p.type==='Cash');function buckets(p){const balance=value(p);let b=state.cash[p.id];if(!b||Math.abs(Object.values(b).reduce((a,n)=>a+n,0)-balance)>.01)return{spending:0,tax:0,committed:0,available:balance};return b}const available=id=>{const p=ledger.positions.find(x=>x.id===id);return p?buckets(p).available:0};const cashTotal=()=>cashPositions().reduce((a,p)=>a+value(p),0);const spare=()=>cashPositions().reduce((a,p)=>a+buckets(p).available,0);
function note(t){$('#notice').textContent=t;setTimeout(()=>$('#notice').textContent='',4000)}function open(html){$('#dialog-content').innerHTML=html;if(!$('#simple-dialog').open)$('#simple-dialog').showModal();bind()}function close(){$('#simple-dialog').close()}function view(){return ['home','money','tax'].includes(location.hash.slice(1))?location.hash.slice(1):'home'}
function liquidInvestments(){return ledger.positions.filter(p=>['ETF','Bonds','Shares'].includes(p.type)&&!p.company).reduce((a,p)=>a+value(p),0)}
function outstanding(){const a=[];if(!state.approved.includes('cs'))a.push(['Review your company details','Draft ready · due 29 November','review']);a.push(['Add two records for your accounts','Year-end broker statement and loan balance confirmation','evidence']);return a}
function home(){const payment=ledger.payments.filter(p=>p.to==='household'&&p.date>='2026-10-17'&&!['Paid','Received'].includes(p.status)).sort((a,b)=>a.date.localeCompare(b.date))[0];const tasks=outstanding();return `<div class="home-heading"><span class="quiet">Your household · personal and company money</span><h1>Your money.</h1></div><section class="money-summary"><div><span class="small-label">Total wealth</span><div class="big-number">${money(wealth())}</div><button class="text-link" data-command="basis">How this is counted ↗</button></div><div class="next-payment"><span class="small-label">Next payment to your household</span><div class="payment-number">${payment?money(payment.amount):'Nothing scheduled'}</div><p>${payment?when(payment.date)+' · '+esc(payment.type):'You’re up to date.'}</p>${payment?'<span class="status">Proposed · Partner approval needed</span>':''}<button class="text-link" data-command="payment">View payment →</button></div></section><section class="needs"><div class="section-heading"><h2>For you to do</h2><span>${tasks.length} ${tasks.length===1?'thing':'things'}</span></div>${tasks.map(([title,sub,command])=>`<button class="task-row" data-command="${command}"><div><strong>${title}</strong><span>${sub}</span></div><span aria-hidden="true">→</span></button>`).join('')}</section><section class="background-work"><h2>Being handled</h2><p>${state.docs.length?state.docs.length+' document'+(state.docs.length===1?' is':'s are')+' waiting for Partner review.':'No new documents waiting for review.'} ${state.requests.length?state.requests.length+' investment request'+(state.requests.length===1?' is':'s are')+' waiting for your Partner.':''} ${state.approved.includes('cs')?'You approved the company details. Filing remains with your Partner.':''}</p><p class="quiet">Bought something? Received an agreement? Use Upload. Planning an investment? Use Invest.</p></section>`}
function moneyPage(){const cash=cashTotal(),rows=ledger.positions.filter(p=>moneyFilter==='cash'?p.type==='Cash':true);return `<div class="page-heading"><h1>Your money.</h1><p>What you own, and what the cash is for.</p></div><div class="cash-summary"><div><span>Cash in your accounts</span><strong>${money(cash)}</strong></div><div><span>Marked available to invest</span><strong>${money(spare())}</strong></div><div><span>Reserved for other things</span><strong>${money(cash-spare())}</strong></div><div><span>Investments you could sell</span><strong>${money(liquidInvestments())}</strong><small>Before tax and settlement</small></div></div><div class="section-heading"><h2>Cash with a job</h2><span>Personal and company cash stay separate</span></div>${cashPositions().map(p=>{const b=buckets(p);return `<div class="cash-row"><div><strong>${esc(p.name)}</strong><span>${esc(owners[p.owner]||p.owner)} · ${money(value(p))}</span></div><div class="cash-purposes"><span>Spending <b>${money(b.spending)}</b></span><span>Tax reserve <b>${money(b.tax)}</b></span><span>Committed <b>${money(b.committed)}</b></span><span>Available <b>${money(b.available)}</b></span></div><button class="secondary" data-cash="${esc(p.id)}">Change purpose</button></div>`}).join('')}<div class="section-heading records-heading"><h2>What you own</h2><div class="filters"><button data-filter="all" aria-pressed="${moneyFilter==='all'}">Everything</button><button data-filter="cash" aria-pressed="${moneyFilter==='cash'}">Cash</button></div></div><div class="table-scroll"><table><thead><tr><th>Investment</th><th>Held by</th><th>Value</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><span>${esc(p.type)} · ${esc(p.wrapper)}</span></td><td>${esc(owners[p.owner]||p.owner)}</td><td>${money(value(p))}</td><td><button class="text-link" data-holding="${esc(p.id)}">Details</button></td></tr>`).join('')}</tbody></table></div><p class="fine">Company shares and the investments inside those companies appear as separate records here. The home total counts their economic value once. Investments you could sell are not cash: prices, settlement and tax still matter.</p><div class="section-heading records-heading"><h2>Your documents</h2><button class="text-link" data-upload>Upload a document ↗</button></div>${state.docs.length?state.docs.map(d=>`<div class="document-row"><div><strong>${esc(d.name)}</strong><span>${esc(d.kind)} · ${esc(d.owner)} · Awaiting Partner review</span></div><small>File details only</small></div>`).join(''):'<p class="quiet">Drop in a share confirmation, tax document or option agreement. Your Partner checks the details before any records change.</p>'}`}
function taxPage(){const owed=ledger.loans.reduce((a,l)=>a+l.balance,0),companyCash=cashPositions().filter(p=>p.owner!=='household').reduce((a,p)=>a+buckets(p).available,0);const limits=[['ISA contributions',20000,ledger.allowances.isa,'Money you can put into an eligible individual savings account this tax year.'],['Personal gains',3000,ledger.allowances.cgt,'Annual exempt amount for eligible personal gains, not a limit on sale proceeds.'],['Personal dividends',500,ledger.allowances.dividend,'Dividend allowance; it is not the same as company dividend income.'],['Eligible startup investments',1000000,ledger.allowances.eis,'Standard EIS investment ceiling. Relief also needs eligibility, enough Income Tax liability and the holding conditions.']];return `<div class="page-heading"><h1>Tax. In plain English.</h1><p>Your personal and company position. UK illustrative figures.</p></div><div class="tax-estimate"><div><span class="small-label">Set aside for tax</span><strong>${money(cashPositions().reduce((a,p)=>a+buckets(p).tax,0))}</strong></div><div><h2>£32,700 estimated tax to pay.</h2><p>Personal: £18,200 for 2025/26. Company: £14,500 for the year ended 31 March 2026. These are illustrative draft estimates, not a live calculation or final bills. Payments on account are not included.</p><p>Your cash reserve is separate. Your accountant confirms each liability and the money needed in each account.</p></div></div><section class="loan-section"><div class="section-heading"><h2>Money the company owes back</h2><span>Interest-free shareholder loans</span></div><div class="loan-numbers"><div><span>Outstanding principal</span><strong>${money(owed)}</strong></div><div><span>Company cash marked available</span><strong>${money(companyCash)}</strong></div></div><p>Repaying a genuine loan principal is normally returning money already lent, rather than paying a dividend. It does not reduce the company’s tax bill. Your Partner checks the balance and liquidity before approving a repayment.</p>${ledger.loans.map(l=>`<div class="plain-row"><span>${esc(l.creditor)} → ${esc(owners[l.borrower]||l.borrower)}</span><strong>${money(l.balance)}</strong></div>`).join('')}<button class="text-link" data-command="payment">See the proposed repayment →</button><details><summary>Should I lend more to the company?</summary><p>A new loan creates no new tax allowance and does not reset a limit. Your Partner compares personal investing, company ownership, your cash needs and the tax on future withdrawals first.</p><p>Company dividends may be exempt where the conditions apply. Interest, fund returns and gains need their own treatment. An exempt company receipt does not make a later payment to you tax-free.</p></details></section><section class="limits-section"><div class="section-heading"><h2>What’s left for 2026/27</h2><span>Illustrative use, subject to verification</span></div>${limits.map(([label,total,used,description])=>`<details class="allowance"><summary><span>${label}</span><strong>${money(Math.max(0,total-used))} left</strong></summary><div class="limit-bar"><i style="width:${Math.min(100,used/total*100)}%"></i></div><p>${money(used)} recorded against ${money(total)}. ${description}</p></details>`).join('')}<div class="plain-row"><div><strong>Pensions and employee shares</strong><p>Needs your scheme and contribution details. We haven’t assumed an allowance.</p></div><button class="secondary" data-upload>Upload details</button></div><p class="fine">ISA and EIS figures are contribution/investment ceilings, not guaranteed tax savings. The higher EIS ceiling for qualifying knowledge-intensive investments needs a separate eligibility check.</p></section><section class="tax-dates"><h2>What’s coming up</h2><div class="plain-row"><span>Your personal return · 2025/26</span><strong>31 Jan 2027</strong></div><div class="plain-row"><span>Company tax payment · period ended 31 Mar 2026</span><strong>1 Jan 2027</strong></div><p class="fine">Illustrative deadlines. Amounts, payments on account and any instalment rules need professional confirmation.</p></section><p class="fine"><a href="https://www.gov.uk/individual-savings-accounts">ISA rules ↗</a> · <a href="https://www.gov.uk/guidance/capital-gains-tax-rates-and-allowances">Capital gains allowance ↗</a> · <a href="https://www.gov.uk/tax-on-dividends">Dividends ↗</a> · <a href="https://www.gov.uk/directors-loans/you-lend-your-company-money">Loans to your company ↗</a></p>`}
function render(){const v=view();document.querySelectorAll('header nav a').forEach(a=>{if(a.hash==='#'+v)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#screen').innerHTML=v==='money'?moneyPage():v==='tax'?taxPage():home();bind()}
function upload(){open(`<span class="small-label">ADD A DOCUMENT</span><h2>Just upload it.</h2><p>A share confirmation, EIS document, employee option grant or agreement. Your Partner will work through it.</p><form id="upload-form"><label class="drop" for="document">Drop a file or choose one<span>PDF, image, document or spreadsheet</span><input id="document" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.csv,.xls,.xlsx,.txt" required></label><label for="kind">What is it? <span class="quiet">Optional if the filename says it</span></label><select id="kind"><option>Let my Partner identify it</option><option>Share purchase</option><option>EIS document</option><option>EMI grant</option><option>Options agreement</option><option>Tax or accounts evidence</option><option>Other</option></select><label for="doc-owner">Who is it for?</label><select id="doc-owner"><option>Personal</option><option>2LR Investments Ltd</option><option>2LR Property Ltd</option><option>Not sure</option></select><button class="primary wide">Add for review (demo) →</button><p class="fine">Local prototype: file contents are not read, stored or sent. Only filename, size and your selections are saved in this browser. No records change until reviewed.</p></form>`);$('#document').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const k=/eis/i.test(f.name)?'EIS document':/emi/i.test(f.name)?'EMI grant':/option/i.test(f.name)?'Options agreement':/share|trade|contract.?note/i.test(f.name)?'Share purchase':'Let my Partner identify it';$('#kind').value=k});$('.drop').addEventListener('dragover',e=>e.preventDefault());$('.drop').addEventListener('drop',e=>{e.preventDefault();const file=e.dataTransfer.files[0];if(!file)return;const transfer=new DataTransfer();transfer.items.add(file);$('#document').files=transfer.files;$('#document').dispatchEvent(new Event('change'))});$('#upload-form').onsubmit=e=>{e.preventDefault();const file=$('#document').files[0];if(!file)return;state.docs.push({id:crypto.randomUUID(),name:file.name,size:file.size,kind:$('#kind').value,owner:$('#doc-owner').value,created:new Date().toISOString()});persist();close();render();note('File details added for review. Nothing was sent.')}}
let investment={};function invest(){investment={path:'known',name:'',amount:'',source:'',goal:'grow',horizon:'Long term'};investStart()}function investStart(){open(`<span class="small-label">INVEST / 1 OF 3</span><h2>What have you got in mind?</h2><div class="choice-list"><button class="choice" id="know"><strong>I know what I want to invest in.</strong><span>Tell ron. what it is. Check the route before money moves.</span></button><button class="choice" id="help"><strong>Help me choose.</strong><span>Start with your goal and ask your Partner for suitable options.</span></button></div><p class="fine">This is a planning request. It does not place a trade or move money.</p>`);$('#know').onclick=()=>{investment.path='known';investDetails()};$('#help').onclick=()=>{investment.path='help';investDetails()}}
function investDetails(){open(`<span class="small-label">INVEST / 2 OF 3</span><h2>${investment.path==='known'?'Tell ron. the basics.':'What should the money do?'}</h2><form id="invest-form">${investment.path==='known'?'<label for="investment-name">What do you want to invest in?</label><input id="investment-name" required placeholder="A startup, gold, shares, a property…">':''}<label for="investment-amount">How much? (£)</label><input id="investment-amount" type="number" min="1" step="0.01" required placeholder="50000"><label for="source">Where will the money come from?</label><select id="source" required><option value="">Choose an account</option>${cashPositions().map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${money(available(p.id))} available</option>`).join('')}<option value="new">New money, not added yet</option></select><label for="objective">What matters most?</label><select id="objective"><option value="grow">Grow — reinvest for the long term</option><option value="balance">Balance — growth and some income</option><option value="return">Return — regular income first</option></select><label for="horizon">When might you need this money back?</label><select id="horizon"><option>Long term</option><option>Within five years</option><option>Within a year</option><option>Not sure</option></select><p class="error" id="invest-error" role="alert"></p><button class="primary wide">Review request →</button></form>`);$('#invest-form').onsubmit=e=>{e.preventDefault();if(investment.path==='known'&&!$('#investment-name').value.trim()){$('#invest-error').textContent='Tell us what you want to invest in.';return}const amount=Number($('#investment-amount').value),source=$('#source').value;if(source!=='new'&&amount>available(source)){$('#invest-error').textContent='This account has '+money(available(source))+' marked available. Choose new money or update its cash purposes first.';return}investment={...investment,name:investment.path==='known'?$('#investment-name').value.trim():'Help choosing an investment',amount,source,goal:$('#objective').value,horizon:$('#horizon').value};investReview()}}
function investReview(){open(`<span class="small-label">INVEST / 3 OF 3</span><h2>Check the request.</h2><dl class="review-list"><dt>Investment</dt><dd>${esc(investment.name)}</dd><dt>Amount</dt><dd>${money(investment.amount)}</dd><dt>Funding</dt><dd>${investment.source==='new'?'New money · funding to confirm':esc(ledger.positions.find(p=>p.id===investment.source).name)}</dd><dt>Objective</dt><dd>${esc({grow:'Long-term growth',balance:'Growth and some income',return:'Regular income'}[investment.goal])}</dd><dt>Access needed</dt><dd>${esc(investment.horizon)}</dd></dl><p>Your Partner will compare suitable investments or ownership routes, available limits, future tax and money you need to keep accessible.</p><p class="fine">No advice is generated by this mock-up. Your Partner must approve recommendations before you see them. This request does not reserve cash or execute an investment.</p><button class="primary wide" id="send-plan">Save planning request (demo) →</button><button class="text-link" id="plan-back">Start again</button>`);$('#plan-back').onclick=investStart;$('#send-plan').onclick=()=>{state.requests.push({...investment,id:crypto.randomUUID(),status:'Awaiting Partner review',created:new Date().toISOString()});persist();close();render();note('Planning request saved locally. No message or trade was sent.')}}
function cashPurpose(id){const p=ledger.positions.find(x=>x.id===id),b=buckets(p);open(`<span class="small-label">CASH PURPOSE</span><h2>${esc(p.name)}</h2><p>${money(value(p))} · ${esc(owners[p.owner])}. Give the cash a job.</p><form id="cash-form">${[['spending','Spending and running costs'],['tax','Tax reserve'],['committed','Already committed'],['available','Available to invest']].map(([k,l])=>`<label for="cash-${k}">${l} (£)</label><input id="cash-${k}" type="number" min="0" step="0.01" required value="${b[k]}">`).join('')}<p class="error" id="cash-error" role="alert"></p><button class="primary wide">Save purposes</button><p class="fine">The four amounts must add up to the account balance. These labels do not transfer money or confirm your tax bill.</p></form>`);$('#cash-form').onsubmit=e=>{e.preventDefault();const n=Object.fromEntries(Object.keys(b).map(k=>[k,Number($('#cash-'+k).value)]));if(Math.abs(Object.values(n).reduce((a,x)=>a+x,0)-value(p))>.01){$('#cash-error').textContent='These amounts need to add up to '+money(value(p))+'.';return}state.cash[id]=n;persist();close();render();note('Cash purposes saved.')}}
function command(c){if(c==='basis')open(`<h2>Each pound, once.</h2><p>The total is your household’s personal holdings, the value of company shares after company debts, and money those companies owe shareholders.</p><p>A company’s assets and its shares are not added twice. Loan receivables and company debts offset in the combined picture.</p><p class="fine">Illustrative valuations, not an HMRC-agreed valuation or money available to spend. Detailed ownership and share records remain in the records view.</p><a class="text-link" href="#money">Open company records ↗</a>`);if(c==='payment')open(`<h2>£7,500 proposed for 16 November.</h2><p>Loan principal repayment from 2LR Investments Ltd to its shareholders, split across the recorded loan accounts.</p><div class="notice-box">Awaiting Partner approval. This is not a confirmed payment.</div><p>Your Partner needs to check company liquidity, commitments and the outstanding balances. You cannot approve or send it from this prototype.</p>`);if(c==='evidence')open(`<h2>Two records for your accounts.</h2><p>For the company year ended 31 March 2026, your accountant needs:</p><ul><li>The broker’s valuation statement at 31 March.</li><li>Confirmation of the money owed on shareholder loans.</li></ul><button class="primary wide" data-upload>Upload a record →</button><p class="fine">Uploaded file details stay pending review. Uploading a document does not automatically clear the task or approve the accounts.</p>`);if(c==='review')open(`<span class="small-label">DRAFT READY · COMPANY DETAILS</span><h2>Are these still correct?</h2><p>Prepared for review in this illustrative workspace. Due 29 November 2026.</p><dl class="review-list"><dt>Company</dt><dd>2LR Investments Ltd</dd><dt>Review date</dt><dd>15 November 2026</dd><dt>Shares issued</dt><dd>1,000 ordinary shares</dd><dt>Ownership</dt><dd>Household · sample register</dd></dl><p>Your Partner’s completed checks and the full draft would appear here before an actual approval.</p><label class="checkbox"><input type="checkbox" id="confirm-draft"> I’ve checked these sample details.</label><button class="primary wide" id="approve-draft" disabled>Approve draft (demo)</button><p class="fine">No signature or filing is sent. This marks the sample draft approved locally; your Partner still handles submission.</p>`);if(c==='review'){$('#confirm-draft').onchange=e=>$('#approve-draft').disabled=!e.target.checked;$('#approve-draft').onclick=()=>{state.approved.push('cs');state.audit.push({action:'Sample company details approved',date:new Date().toISOString()});persist();close();render();note('Sample draft approved. Nothing was filed.')}}}
function bind(){document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>{if($('#simple-dialog').open)close();upload()});document.querySelectorAll('[data-invest]').forEach(b=>b.onclick=invest);document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>command(b.dataset.command));document.querySelectorAll('[data-cash]').forEach(b=>b.onclick=()=>cashPurpose(b.dataset.cash));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{moneyFilter=b.dataset.filter;render()});document.querySelectorAll('[data-holding]').forEach(b=>b.onclick=()=>{const p=ledger.positions.find(x=>x.id===b.dataset.holding);open(`<h2>${esc(p.name)}</h2><dl class="review-list"><dt>Held by</dt><dd>${esc(owners[p.owner]||p.owner)}</dd><dt>Quantity</dt><dd>${Number(p.qty).toLocaleString('en-GB')}</dd><dt>Value per unit</dt><dd>${money(value(p)/p.qty)}</dd><dt>Total value</dt><dd>${money(value(p))}</dd><dt>Tax record</dt><dd>${esc(p.tax)}</dd><dt>Liquidity</dt><dd>${p.type==='Cash'?'Cash':['ETF','Bonds','Shares'].includes(p.type)&&!p.company?'Tradable · tax and settlement apply':'Not assumed readily available'}</dd></dl>${p.type!=='Cash'?`<form id="asset-purpose-form"><label for="asset-purpose">What is this money for?</label><select id="asset-purpose">${['Not set','Long-term growth','Regular income','Future spending','Emergency reserve','Planned investment funding'].map(x=>`<option ${state.assetPurposes[p.id]===x?'selected':''}>${x}</option>`).join('')}</select><button class="secondary wide">Save purpose</button></form>`:''}<p class="fine">${p.type==='Cash'?'Cash purpose is managed separately.':p.type==='Property'||p.company?'Not assumed available as spendable cash.':'Selling investments requires settlement and may create tax.'}</p><a class="text-link" href="#money">Detailed holding records ↗</a>`);if(p.type!=='Cash')$('#asset-purpose-form').onsubmit=e=>{e.preventDefault();state.assetPurposes[p.id]=$('#asset-purpose').value;persist();close();render();note('Investment purpose saved.')}})}
$('#simple-dialog .close').onclick=close;$('#simple-dialog').addEventListener('click',e=>{if(e.target===$('#simple-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});function themeLabel(){$('#theme').setAttribute('aria-label',document.documentElement.dataset.theme==='dark'?'Switch to light mode':'Switch to dark mode')}$('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('ron-appearance',document.documentElement.dataset.theme);themeLabel()};$('#reset-simple').onclick=()=>{state=structuredClone(defaults);persist();render();note('Prototype changes reset. Detailed records were kept.')};document.querySelectorAll('header nav a,header .logo').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();history.pushState(null,'',a.hash);render();window.scrollTo({top:0})}));window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0})});themeLabel();render();
